SourceCode.Declaration:
/// <summary>
/// One row of HSMobileOpsWorkerDirectoryResponse::parmWorkers - enough to render and search the
/// Admin Center's worker list. Deliberately thin: nothing here needs the password/lockout
/// columns that HSMobileOpsUserService::signIn itself deals with.
/// </summary>
[DataContractAttribute]
class HSMobileOpsWorkerSummary
{
    str     userName;
    str     displayName;
    boolean isSupervisor;

}

Method.Source:
[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

[DataMemberAttribute('DisplayName')]
public str parmDisplayName(str _value = displayName)
{
    displayName = _value;
    return displayName;
}

[DataMemberAttribute('IsSupervisor')]
public boolean parmIsSupervisor(boolean _value = isSupervisor)
{
    isSupervisor = _value;
    return isSupervisor;
}
